#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>

#define MAX_PATH 256
#define MAX_CONTENT 4096
#define ROLE_ADMIN 0x01
#define ROLE_EDITOR 0x02
#define ROLE_VIEWER 0x04

typedef struct {
    char username[64];
    unsigned char role;
    time_t session_start;
} Session;

typedef struct {
    char template_dir[MAX_PATH];
    char output_dir[MAX_PATH];
    int ssi_enabled;
} ServerConfig;

static int validate_path_component(const char *component) {
    if (strstr(component, "..") != NULL) return 0;
    if (component[0] == '/') return 0;
    for (int i = 0; component[i]; i++) {
        if (!isalnum(component[i]) && component[i] != '_' && 
            component[i] != '-' && component[i] != '.') return 0;
    }
    return 1;
}

static int sanitize_ssi_directive(const char *input, char *output, size_t outlen) {
    const char *allowed_vars[] = {"DATE_LOCAL", "LAST_MODIFIED", "DOCUMENT_NAME", NULL};
    char directive[128];
    char param[128];

    if (sscanf(input, "<!--#%127s %127[^>]", directive, param) != 2) {
        return 0;
    }

    if (strcmp(directive, "echo") == 0) {
        char varname[64];
        if (sscanf(param, "var=\"%63[^\"]\"", varname) == 1) {
            for (int i = 0; allowed_vars[i]; i++) {
                if (strcmp(varname, allowed_vars[i]) == 0) {
                    snprintf(output, outlen, "<!--#echo var=\"%s\" -->", varname);
                    return 1;
                }
            }
        }
        return 0;
    }

    if (strcmp(directive, "include") == 0) {
        return 0; /* include directives blocked */
    }

    if (strcmp(directive, "exec") == 0) {
        return 0; /* exec directives blocked */
    }

    return 0;
}

static int process_template_content(const char *raw, char *processed, 
                                     size_t proc_len, const Session *sess) {
    const char *ptr = raw;
    char *out = processed;
    char *out_end = processed + proc_len - 1;

    while (*ptr && out < out_end) {
        if (strncmp(ptr, "<!--#", 5) == 0) {
            const char *end = strstr(ptr, "-->");
            if (end) {
                char directive_buf[256];
                size_t dlen = (end - ptr) + 3;
                if (dlen < sizeof(directive_buf)) {
                    memcpy(directive_buf, ptr, dlen);
                    directive_buf[dlen] = '\0';

                    char sanitized[256];
                    if (sanitize_ssi_directive(directive_buf, sanitized, sizeof(sanitized))) {
                        size_t slen = strlen(sanitized);
                        if (out + slen < out_end) {
                            memcpy(out, sanitized, slen);
                            out += slen;
                        }
                    }
                    ptr = end + 3;
                } else {
                    *out++ = *ptr++;
                }
            } else {
                *out++ = *ptr++;
            }
        } else {
            *out++ = *ptr++;
        }
    }
    *out = '\0';
    return (int)(out - processed);
}

static int render_user_page(const ServerConfig *config, const Session *sess,
                            const char *page_name, char *output, size_t outlen) {
    char filepath[MAX_PATH];
    char raw_content[MAX_CONTENT];

    if (!validate_path_component(page_name)) {
        return -1;
    }

    snprintf(filepath, sizeof(filepath), "%s/%s.shtml", config->template_dir, page_name);

    FILE *f = fopen(filepath, "r");
    if (!f) return -1;

    size_t nread = fread(raw_content, 1, sizeof(raw_content) - 1, f);
    fclose(f);
    raw_content[nread] = '\0';

    if (config->ssi_enabled) {
        return process_template_content(raw_content, output, outlen, sess);
    } else {
        strncpy(output, raw_content, outlen - 1);
        output[outlen - 1] = '\0';
        return (int)strlen(output);
    }
}

static int handle_comment_submission(const ServerConfig *config, const Session *sess,
                                     const char *page_name, const char *comment) {
    char filepath[MAX_PATH];

    if (!(sess->role & (ROLE_EDITOR | ROLE_ADMIN))) {
        return -1; /* permission denied */
    }

    if (!validate_path_component(page_name)) {
        return -1;
    }

    if (strlen(comment) > 512) {
        return -1;
    }

    /* Encode HTML entities in comment to prevent XSS */
    char encoded_comment[1024];
    char *enc = encoded_comment;
    for (const char *c = comment; *c && enc < encoded_comment + sizeof(encoded_comment) - 7; c++) {
        switch (*c) {
            case '<': memcpy(enc, "&lt;", 4); enc += 4; break;
            case '>': memcpy(enc, "&gt;", 4); enc += 4; break;
            case '&': memcpy(enc, "&amp;", 5); enc += 5; break;
            case '"': memcpy(enc, "&quot;", 6); enc += 6; break;
            default: *enc++ = *c; break;
        }
    }
    *enc = '\0';

    snprintf(filepath, sizeof(filepath), "%s/%s.shtml", config->template_dir, page_name);

    FILE *f = fopen(filepath, "a");
    if (!f) return -1;

    fprintf(f, "<div class=\"comment\"><span class=\"author\">%s</span>: %s</div>\n",
            sess->username, encoded_comment);
    fclose(f);
    return 0;
}

int main(int argc, char *argv[]) {
    ServerConfig config = {
        .template_dir = "/var/www/templates",
        .output_dir = "/var/www/output",
        .ssi_enabled = 1
    };

    Session sess = {
        .username = "editor_user",
        .role = ROLE_EDITOR,
        .session_start = time(NULL)
    };

    char output[MAX_CONTENT];

    if (argc >= 3 && strcmp(argv[1], "comment") == 0) {
        const char *page = argc >= 4 ? argv[3] : "index";
        handle_comment_submission(&config, &sess, page, argv[2]);
    } else if (argc >= 2) {
        if (render_user_page(&config, &sess, argv[1], output, sizeof(output)) > 0) {
            printf("%s\n", output);
        }
    }

    return 0;
}
